#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {  // Child process
        char *args[] = {"ls", "-l", NULL};
        execvp("ls", args);  // Replace child with 'ls -l' command
        printf("execvp failed\n");  // This line won't execute if execvp succeeds
    } else if (pid > 0) {  // Parent process
        wait(NULL);  // Wait for child to finish
    }
    return 0;
}
